{
  "done": false,
  "tool": "manage_backends",
  "args": {
    "operation": "refresh",
    "backend_id": "backend_001",
    "widgets_json": {
      "estimate_revisions": {
        "data": {
          "table": {
            "columnsDefs": [
              {
                "cellDataType": "text",
                "field": "quarter",
                "headerName": "Quarter"
              },
              {
                "cellDataType": "number",
                "field": "eps_estimate",
                "headerName": "EPS Est"
              },
              {
                "cellDataType": "number",
                "field": "revenue_estimate_b",
                "headerName": "Revenue Est ($B)"
              }
            ]
          }
        },
        "description": "Street estimate revisions by quarter.",
        "endpoint": "/estimate-revisions",
        "gridData": {
          "h": 9,
          "w": 20
        },
        "name": "Estimate Revisions",
        "params": [
          {
            "label": "Symbol",
            "optionsEndpoint": "/symbols",
            "paramName": "symbol",
            "type": "endpoint",
            "value": "NVDA"
          }
        ],
        "type": "table",
        "staleTime": 900000
      },
      "earnings_chart": {
        "description": "Plotly EPS beat/miss history.",
        "endpoint": "/eps-history",
        "gridData": {
          "h": 9,
          "w": 12
        },
        "name": "EPS History",
        "params": [
          {
            "label": "Symbol",
            "optionsEndpoint": "/symbols",
            "paramName": "symbol",
            "type": "endpoint",
            "value": "NVDA"
          }
        ],
        "type": "chart"
      },
      "earnings_note": {
        "description": "Preview note for the earnings call.",
        "endpoint": "/earnings-preview",
        "gridData": {
          "h": 6,
          "w": 8
        },
        "name": "Earnings Preview",
        "params": [
          {
            "label": "Symbol",
            "optionsEndpoint": "/symbols",
            "paramName": "symbol",
            "type": "endpoint",
            "value": "NVDA"
          }
        ],
        "type": "markdown"
      }
    },
    "apps_json": [
      {
        "name": "Full Earnings Sync",
        "description": "Three earnings widgets synced by symbol.",
        "tabs": {
          "full": {
            "id": "full",
            "layout": [
              {
                "i": "estimate_revisions",
                "x": 0,
                "y": 0,
                "w": 20,
                "h": 9
              },
              {
                "i": "earnings_chart",
                "x": 20,
                "y": 0,
                "w": 12,
                "h": 9
              },
              {
                "i": "earnings_note",
                "x": 32,
                "y": 0,
                "w": 8,
                "h": 6
              }
            ],
            "name": "Full",
            "groups": [
              {
                "name": "Full Symbol Sync",
                "type": "param",
                "paramName": "symbol",
                "widgetIds": [
                  "estimate_revisions",
                  "earnings_chart",
                  "earnings_note"
                ]
              }
            ]
          }
        }
      }
    ]
  }
}
